#!/usr/bin/env bash
# ============================================================================
#  GSZ step112 — WhatsApp verification-bot QR + live status in admin (#9).
#  Bot (gszwabot): captures the current QR + connection state and serves /qr
#  (localhost only). Main app: proxies it (secret-gated) and renders a QR PNG
#  on a new admin page /admin/wabot that auto-refreshes. The bot's restart is
#  safe — it reconnects from saved creds, no re-scan needed.
#  Patches TWO dirs + restarts TWO processes. Full rollback on any failure.
# ============================================================================
set -euo pipefail
GSZ=/opt/gsz
WABOT=/opt/gsz-wabot
TS=$(date +%Y%m%d-%H%M%S)
BK="$GSZ/.bak-step112-$TS"
TMP=$(mktemp -d)

echo "==> step112: WhatsApp bot QR on admin"
[ -f "$WABOT/bot.js" ] || { echo "!! $WABOT/bot.js not found"; exit 1; }

echo "==> ensuring qrcode is installed (main app)"
( cd "$GSZ" && npm install qrcode --no-audit --no-fund --silent ) || { echo "!! npm install qrcode failed (network?). Nothing changed."; exit 1; }

mkdir -p "$BK"
cp "$GSZ/server.js" "$BK/server.js"
cp "$GSZ/views/admin/_shell_top.ejs" "$BK/_shell_top.ejs"
cp "$WABOT/bot.js" "$BK/bot.js"
HAD_WJS=0;  [ -f "$GSZ/routes/wabot.js" ] && { HAD_WJS=1;  cp "$GSZ/routes/wabot.js" "$BK/wabot.js"; }
HAD_WEJS=0; [ -f "$GSZ/views/admin/wabot.ejs" ] && { HAD_WEJS=1; cp "$GSZ/views/admin/wabot.ejs" "$BK/wabot.ejs"; }
echo "    backup: $BK"

restore() {
  echo "!!  FAILED — restoring previous files"
  cp "$BK/server.js" "$GSZ/server.js"
  cp "$BK/_shell_top.ejs" "$GSZ/views/admin/_shell_top.ejs"
  cp "$BK/bot.js" "$WABOT/bot.js"
  if [ "$HAD_WJS" = "1" ];  then cp "$BK/wabot.js" "$GSZ/routes/wabot.js"; else rm -f "$GSZ/routes/wabot.js"; fi
  if [ "$HAD_WEJS" = "1" ]; then cp "$BK/wabot.ejs" "$GSZ/views/admin/wabot.ejs"; else rm -f "$GSZ/views/admin/wabot.ejs"; fi
  pm2 restart gsz >/dev/null 2>&1 || true
  pm2 restart gszwabot >/dev/null 2>&1 || true
  echo "!!  restored. no changes kept."
}
trap 'restore' ERR

echo "" | base64 -d > "$TMP/patch_step112.js"

echo "==> writing new files (main app)"
mkdir -p "$GSZ/routes" "$GSZ/views/admin"
echo ""  | base64 -d > "$GSZ/routes/wabot.js"
echo "" | base64 -d > "$GSZ/views/admin/wabot.ejs"

echo "==> applying patches (main app + bot)"
node "$TMP/patch_step112.js" "$GSZ" "$WABOT"

echo "==> validating"
node --check "$GSZ/server.js"
node --check "$GSZ/routes/wabot.js"
node --check "$WABOT/bot.js"
node -e "const ejs=require('$GSZ/node_modules/ejs');['views/admin/wabot.ejs','views/admin/_shell_top.ejs'].forEach(function(f){ejs.compile(require('fs').readFileSync('$GSZ/'+f,'utf8'),{filename:'$GSZ/'+f});console.log('    ejs ok '+f)})"

echo "==> restarting app + bot"
pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
pm2 restart gszwabot >/dev/null 2>&1 || pm2 restart gszwabot
sleep 3

echo "==> health checks"
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true)
[ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }
AC=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/admin/wabot || true)
[ "$AC" = "200" ] || [ "$AC" = "302" ] && echo "    /admin/wabot reachable ($AC): OK" || { echo "    /admin/wabot $AC"; false; }
SEC=$(cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node -e "require('dotenv/config');const{Pool}=require('pg');const p=new Pool({host:process.env.DB_HOST,port:+(process.env.DB_PORT||5432),user:process.env.DB_USER,password:process.env.DB_PASS,database:process.env.DB_NAME});p.query(\"SELECT value FROM wa_settings WHERE key='wa_bot_webhook_secret'\").then(function(r){console.log(r.rows[0]?r.rows[0].value:'');return p.end();}).catch(function(){console.log('')})" 2>/dev/null || true)
if [ -n "$SEC" ]; then
  QR=$(curl -s -H "X-WA-Secret: $SEC" http://127.0.0.1:8095/qr || true)
  if grep -q '"ok":true' <<<"$QR"; then echo "    bot /qr endpoint live: OK  ($(grep -o '\"status\":\"[a-z_]*\"' <<<\"$QR\" | head -1))"; else echo "    bot /qr check: $QR  (bot may still be starting — the page will update live)"; fi
else
  echo "    (couldn't read bot secret to test /qr directly — non-fatal)"
fi

trap - ERR
rm -rf "$TMP"
echo ""
echo "==> step112 OK ✅"
echo "    • New admin page: WhatsApp bot (/admin/wabot) — live status, auto-refreshing."
echo "    • If the bot ever logs out, a scannable QR appears there (no terminal needed)."
echo "    • Bot reconnected from saved creds, so it did NOT need a re-scan just now."
